namespace {
template<class T>T symbol(QLibrary& lib,const char* name){auto s=lib.resolve(name);if(!s)throw std::runtime_error(std::string("API SoapySDR manquante : ")+name);return reinterpret_cast<T>(s);}
#define API(name) symbol<decltype(&SoapySDR##name)>(lib,"SoapySDR" #name)
class Api {
public:QLibrary lib;SoapySDRDevice* device=nullptr;SoapySDRStream* stream=nullptr;
 Api(){static QMutex environment;{QMutexLocker lock(&environment);auto dir=QCoreApplication::applicationDirPath()+"/sdr-modules";if(qEnvironmentVariableIsEmpty("SOAPY_SDR_PLUGIN_PATH")&&QDir(dir).exists())qputenv("SOAPY_SDR_PLUGIN_PATH",dir.toUtf8());}
  const bool forced=!qEnvironmentVariableIsEmpty("POCSAG_TEST_SOAPY_LIBRARY")||!qEnvironmentVariableIsEmpty("POCSAG_SOAPY_LIBRARY");lib.setFileName(qEnvironmentVariable("POCSAG_TEST_SOAPY_LIBRARY",qEnvironmentVariable("POCSAG_SOAPY_LIBRARY",QCoreApplication::applicationDirPath()+"/libSoapySDR.dll")));if(!lib.load()){if(!forced){lib.setFileName("SoapySDR");lib.load();}if(!lib.isLoaded())throw std::runtime_error(("SoapySDR indisponible : "+lib.fileName()+" — "+lib.errorString()+". Vérifier la DLL x64 et ses dépendances.").toStdString());}
  auto abi=symbol<const char*(*)()>(lib,"SoapySDR_getABIVersion")();if(!abi||QString::fromLatin1(abi)!="0.8")throw std::runtime_error("ABI SoapySDR incompatible (0.8 requis)");
 }
 ~Api(){if(stream){auto deactivate=reinterpret_cast<decltype(&SoapySDRDevice_deactivateStream)>(lib.resolve("SoapySDRDevice_deactivateStream"));auto close=reinterpret_cast<decltype(&SoapySDRDevice_closeStream)>(lib.resolve("SoapySDRDevice_closeStream"));if(deactivate)deactivate(device,stream,0,0);if(close)close(device,stream);}if(device){auto unmake=reinterpret_cast<decltype(&SoapySDRDevice_unmake)>(lib.resolve("SoapySDRDevice_unmake"));if(unmake)unmake(device);}}
 void check(int n){if(n<0)throw std::runtime_error(QString("SoapySDR : %1 (code %2)").arg(QString::fromUtf8(API(Device_lastError)())).arg(n).toStdString());}
 void open(QString key){if(!key.startsWith("soapy:"))throw std::runtime_error("Identifiant Soapy invalide");auto bytes=QByteArray::fromBase64(key.mid(6).toLatin1(),QByteArray::Base64UrlEncoding);auto json=QJsonDocument::fromJson(bytes);if(!json.isObject()||json.object().isEmpty())throw std::runtime_error("Identifiant Soapy incomplet");SoapySDRKwargs args{};auto object=json.object();for(auto it=object.begin();it!=object.end();++it)if(API(Kwargs_set)(&args,it.key().toUtf8().constData(),it.value().toString().toUtf8().constData())!=0){API(Kwargs_clear)(&args);throw std::runtime_error("Mémoire arguments Soapy insuffisante");}device=API(Device_make)(&args);API(Kwargs_clear)(&args);if(!device)throw std::runtime_error(QString::fromUtf8(API(Device_lastError)()).toStdString());if(API(Device_getNumChannels)(device,SOAPY_SDR_RX)==0)throw std::runtime_error("Ce périphérique ne possède aucun canal RX");}
 SdrCapabilities caps(){SdrCapabilities c;c.backend="SoapySDR 0.8";size_t n=0;auto ranges=API(Device_getFrequencyRange)(device,SOAPY_SDR_RX,0,&n);for(size_t i=0;i<n;++i){if(!i)c.frequencyMin=ranges[i].minimum;c.frequencyMin=std::min(c.frequencyMin,ranges[i].minimum);c.frequencyMax=std::max(c.frequencyMax,ranges[i].maximum);}API(_free)(ranges);
  auto gain=API(Device_getGainRange)(device,SOAPY_SDR_RX,0);c.gainMin=gain.minimum;c.gainMax=gain.maximum;c.agc=API(Device_hasGainMode)(device,SOAPY_SDR_RX,0);c.ppm=API(Device_hasFrequencyCorrection)(device,SOAPY_SDR_RX,0);
  auto rates=API(Device_listSampleRates)(device,SOAPY_SDR_RX,0,&n);for(size_t i=0;i<n&&i<10000;++i)if(std::isfinite(rates[i])&&rates[i]>0)c.rates<<rates[i];API(_free)(rates);auto rateRanges=API(Device_getSampleRateRange)(device,SOAPY_SDR_RX,0,&n);for(size_t i=0;i<n;++i){if(!i)c.rateMin=rateRanges[i].minimum;c.rateMin=std::min(c.rateMin,rateRanges[i].minimum);c.rateMax=std::max(c.rateMax,rateRanges[i].maximum);}API(_free)(rateRanges);
  auto bw=API(Device_getBandwidthRange)(device,SOAPY_SDR_RX,0,&n);c.bandwidth=n>0;API(_free)(bw);auto antennas=API(Device_listAntennas)(device,SOAPY_SDR_RX,0,&n);for(size_t i=0;i<n;++i)c.antennas<<QString::fromUtf8(antennas[i]);API(Strings_clear)(&antennas,n);auto gains=API(Device_listGains)(device,SOAPY_SDR_RX,0,&n);for(size_t i=0;i<n;++i)c.gains<<QString::fromUtf8(gains[i]);API(Strings_clear)(&gains,n);return c;
 }
};
}
QString SoapyRadio::diagnostics(){try{Api api;auto& lib=api.lib;QStringList lines{"Runtime Soapy chargé : "+lib.fileName()};auto paths=reinterpret_cast<char**(*)(size_t*)>(lib.resolve("SoapySDR_listSearchPaths"));auto modules=reinterpret_cast<char**(*)(size_t*)>(lib.resolve("SoapySDR_listModules"));auto loader=reinterpret_cast<SoapySDRKwargs(*)(const char*)>(lib.resolve("SoapySDR_getLoaderResult"));if(paths){size_t n=0;auto list=paths(&n);for(size_t i=0;i<n;++i)lines<<"Recherche modules : "+QString::fromUtf8(list[i]);API(Strings_clear)(&list,n);}if(modules){size_t n=0;auto list=modules(&n);for(size_t i=0;i<n;++i){lines<<"Module présent : "+QString::fromUtf8(list[i]);if(loader){auto result=loader(list[i]);for(size_t j=0;j<result.size;++j)lines<<QString("  %1 : %2").arg(QString::fromUtf8(result.keys[j]),QString::fromUtf8(result.vals[j]).isEmpty()?QString("chargé ; IQ à tester"):QString::fromUtf8(result.vals[j]));API(Kwargs_clear)(&result);}}if(!n)lines<<"Aucun module Soapy trouvé dans ces dossiers.";API(Strings_clear)(&list,n);}return lines.join('\n');}catch(const std::exception& e){return QString::fromUtf8(e.what());}}
QVector<RadioDevice> SoapyRadio::devices(QString* diagnostic){QVector<RadioDevice> result;try{Api api;auto& lib=api.lib;size_t n=0;auto list=API(Device_enumerate)(nullptr,&n);for(size_t i=0;i<n;++i){QJsonObject object;for(size_t j=0;j<list[i].size;++j)object.insert(QString::fromUtf8(list[i].keys[j]),QString::fromUtf8(list[i].vals[j]));auto driver=object.value("driver").toString();QString label=object.value("label").toString();if(label.isEmpty())label=driver;auto serial=object.value("serial").toString();result.push_back({label+" — "+serial+" [Soapy:"+driver+"]","soapy:"+QString::fromLatin1(QJsonDocument(object).toJson(QJsonDocument::Compact).toBase64(QByteArray::Base64UrlEncoding))});}API(KwargsList_clear)(list,n);if(diagnostic)*diagnostic=QString("SoapySDR : %1 périphérique(s) accessible(s). Les modules et pilotes restent propres à chaque famille.").arg(n);}catch(const std::exception& e){if(diagnostic)*diagnostic=QString::fromUtf8(e.what());}return result;}
SdrCapabilities SoapyRadio::capabilities(QString key){try{Api api;api.open(key);return api.caps();}catch(const std::exception& e){SdrCapabilities c;c.error=QString::fromUtf8(e.what());return c;}}
void SoapyRadio::receive(const RadioConfig& config,std::atomic_bool& stopping,const std::function<void(QByteArray)>& samples,const std::function<void(quint32,quint32)>& tuned,const std::function<void(QString)>& problem){
 if(config.rate<48000||config.rate>20000000)throw std::runtime_error("Adaptateur Soapy : taux logiciel de 48 kéch/s à 20 Méch/s requis");Api api;api.open(config.deviceKey);auto& lib=api.lib;auto device=api.device;auto caps=api.caps();api.check(API(Device_setSampleRate)(device,SOAPY_SDR_RX,0,config.rate));api.check(API(Device_setFrequency)(device,SOAPY_SDR_RX,0,config.frequency,nullptr));if(config.ppm){if(!caps.ppm)throw std::runtime_error("Correction PPM non prise en charge par ce module");api.check(API(Device_setFrequencyCorrection)(device,SOAPY_SDR_RX,0,config.ppm));}if(config.automaticGain&&!caps.agc)throw std::runtime_error("AGC indisponible sur ce matériel");if(caps.agc)api.check(API(Device_setGainMode)(device,SOAPY_SDR_RX,0,config.automaticGain));if(!config.automaticGain&&!caps.gains.isEmpty())api.check(API(Device_setGain)(device,SOAPY_SDR_RX,0,config.gain/10.));if(config.bandwidth){if(!caps.bandwidth)throw std::runtime_error("Bande matérielle non réglable");api.check(API(Device_setBandwidth)(device,SOAPY_SDR_RX,0,config.bandwidth));}if(!config.antenna.isEmpty()){if(!caps.antennas.contains(config.antenna))throw std::runtime_error("Antenne non disponible");api.check(API(Device_setAntenna)(device,SOAPY_SDR_RX,0,config.antenna.toUtf8().constData()));}
 // Feed actual read-back rate/frequency downstream, not merely the requested values.
 double actualRate=API(Device_getSampleRate)(device,SOAPY_SDR_RX,0),actualFrequency=API(Device_getFrequency)(device,SOAPY_SDR_RX,0);if(!std::isfinite(actualFrequency)||actualFrequency<0||actualFrequency>4294967295.0)throw std::runtime_error("Fréquence appliquée hors plage logicielle");if(!std::isfinite(actualRate)||std::abs(actualRate-config.rate)>1)throw std::runtime_error("Le taux IQ appliqué diffère du taux demandé ; ajustez les paramètres");
 size_t channel=0;api.stream=API(Device_setupStream)(device,SOAPY_SDR_RX,"CF32",&channel,1,nullptr);if(!api.stream)throw std::runtime_error(QString::fromUtf8(API(Device_lastError)()).toStdString());api.check(API(Device_activateStream)(device,api.stream,0,0,0));tuned(quint32(std::llround(actualFrequency)),quint32(std::llround(actualRate)));std::vector<float> data(32768);void* buffers[]={data.data()};QElapsedTimer last,overflow;last.start();overflow.start();while(!stopping){int flags=0;long long time=0;int count=API(Device_readStream)(device,api.stream,buffers,16384,&flags,&time,100000);if(count==SOAPY_SDR_TIMEOUT||count==0){if(last.elapsed()>3000)throw std::runtime_error("SoapySDR : aucun IQ depuis trois secondes");continue;}if(count==SOAPY_SDR_OVERFLOW){if(last.elapsed()>3000)throw std::runtime_error("SoapySDR : débordements sans IQ exploitable depuis trois secondes");if(overflow.elapsed()>1000){problem("SoapySDR : débordement IQ, réduire le taux ou le nombre de récepteurs");overflow.restart();}continue;}api.check(count);if(count>16384)throw std::runtime_error("Taille de tampon Soapy invalide");auto bytes=IqConversion::floats(data.data(),count);last.restart();samples(bytes);}
}
